using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();
        string inputText = args["rawInput"].ToString();

        // Parse input: !pvp @opponent wager
        if (string.IsNullOrEmpty(inputText)) {
            CPH.SendMessage($"@{userName}, usage: !pvp @opponent [wager]. Example: !pvp @user 5 (wager 1-20 RRTokens)");
            return false;
        }

        string[] parts = inputText.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length < 2) {
            CPH.SendMessage($"@{userName}, usage: !pvp @opponent [wager]. Example: !pvp @user 5");
            return false;
        }

        string opponentName = parts[0].TrimStart('@');
        int wager;

        if (!int.TryParse(parts[1], out wager) || wager < 1 || wager > 20) {
            CPH.SendMessage($"@{userName}, wager must be between 1 and 20 RRTokens!");
            return false;
        }

        // Get opponent user ID
        var opponentInfo = CPH.TwitchGetUser(opponentName);
        if (opponentInfo == null) {
            CPH.SendMessage($"@{userName}, user @{opponentName} not found.");
            return false;
        }

        string opponentId = opponentInfo.UserId;
        opponentName = opponentInfo.UserLogin;

        // Can't challenge yourself
        if (userId == opponentId) {
            CPH.SendMessage($"@{userName}, you can't challenge yourself!");
            return false;
        }

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"@{userName}, egg data not found!");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Check both players have sufficient tokens
        if (data["users"] == null || data["users"][userId] == null) {
            CPH.SendMessage($"@{userName}, you don't have any RRTokens! Use !buyRRT to purchase some.");
            return false;
        }

        if (data["users"][opponentId] == null) {
            CPH.SendMessage($"@{userName}, @{opponentName} doesn't have any RRTokens yet!");
            return false;
        }

        int challengerTokens = (int)(data["users"][userId]["rrTokens"] ?? 0);
        int opponentTokens = (int)(data["users"][opponentId]["rrTokens"] ?? 0);

        if (challengerTokens < wager) {
            CPH.SendMessage($"@{userName}, you don't have enough RRTokens! You have {challengerTokens}, need {wager}.");
            return false;
        }

        if (opponentTokens < wager) {
            CPH.SendMessage($"@{userName}, @{opponentName} doesn't have enough RRTokens! They have {opponentTokens}, need {wager}.");
            return false;
        }

        // Create PvP challenge
        if (data["pvpChallenges"] == null) {
            data["pvpChallenges"] = new JObject();
        }

        // Store challenge (key: opponentId, value: challenge data)
        data["pvpChallenges"][opponentId] = new JObject();
        data["pvpChallenges"][opponentId]["challengerId"] = userId;
        data["pvpChallenges"][opponentId]["challengerName"] = userName;
        data["pvpChallenges"][opponentId]["wager"] = wager;
        data["pvpChallenges"][opponentId]["timestamp"] = DateTime.UtcNow.ToString("o");

        File.WriteAllText(dataPath, data.ToString());

        CPH.SendMessage($"⚔️ @{userName} challenges @{opponentName} to a PvP battle! Wager: {wager} RRTokens each. @{opponentName}, type !accept within 60 seconds to accept!");

        return true;
    }
}
